function allCaseSpellings(s: string): string[] {
  let out = [""];
  for (const ch of s) {
    const lo = ch.toLowerCase(), up = ch.toUpperCase();
    const next: string[] = [];
    for (const p of out) {
      next.push(p + lo);
      if (up !== lo) next.push(p + up);
    }
    out = next;
  }
  return out;
}

