function allCaseSpellings(s: string): string[] {
  const buf = s.split(""), out: string[] = [];
  const go = (i: number) => {
    if (i === buf.length) { out.push(buf.join("")); return; }
    const lo = buf[i].toLowerCase(), up = buf[i].toUpperCase();
    if (lo === up) { go(i + 1); return; } // a digit
    buf[i] = lo; go(i + 1);
    buf[i] = up; go(i + 1);
  };
  go(0);
  return out;
}

