    def allCaseSpellings(self, s: str) -> List[str]:
        buf, out = list(s), []

        def go(i):
            if i == len(buf):
                out.append("".join(buf))
                return
            if not buf[i].isalpha():
                go(i + 1)
                return
            for c in (buf[i].lower(), buf[i].upper()):
                buf[i] = c
                go(i + 1)

        go(0)
        return out

