function allCaseSpellings(s: string): string[] {
  const letters: number[] = [];
  for (let i = 0; i < s.length; i++) if (s[i].toLowerCase() !== s[i].toUpperCase()) letters.push(i);
  const out: string[] = [];
  for (let mask = 0; mask < 1 << letters.length; mask++) {
    const buf = s.split("");
    letters.forEach((pos, b) => { buf[pos] = mask >> b & 1 ? buf[pos].toUpperCase() : buf[pos].toLowerCase(); });
    out.push(buf.join(""));
  }
  return out;
}

