class Solution:
    def allCaseSpellings(self, s: str) -> List[str]:
        letters = [i for i, ch in enumerate(s) if ch.isalpha()]
        out = []
        for mask in range(1 << len(letters)):
            buf = list(s)
            for b, pos in enumerate(letters):
                buf[pos] = buf[pos].upper() if mask >> b & 1 else buf[pos].lower()
            out.append("".join(buf))
        return out

